  ui_story_31150601_42_dialog_content = "Se continuarmos assim, todos nós seremos eliminados eventualmente!",
  ui_story_31150601_43_dialog_content = "Descontinuado...? Quer dizer que...",
  ui_story_31150601_44_dialog_content = "Isso significa ultrapassado e obsoleto!",
  ui_story_31150601_45_dialog_content = "Muitas pessoas hoje em dia não usam mais a União Mensageira, esses pequenos correios também podem atender às suas necessidades.",
  ui_story_31150601_46_dialog_content = "Certo. Da última vez que eu estava fazendo uma entrega, o cliente me perguntou se a União Mensageira oferece algum outro tipo de serviço de correspondência...",
