  ui_story_31150601_49_dialog_content = "Exatamente!",
  ui_story_31150601_50_dialog_content = "Porque todos na União Mensageira têm essa ideia, a união gradualmente perde sua relevância!",
  ui_story_31150601_51_dialog_content = "Não concorda, Senhora Naroxel?",
  ui_story_31150601_52_dialog_content = "Vou considerar cuidadosamente tudo o que você disse.",
