  ui_story_31150601_60_option_content = "Acho que você é uma PESSOA ocupada.",
  ui_story_31150601_61_dialog_content = "May Eu pergunto... o que exatamente você quer dizer com isso?",
  ui_story_31150601_62_dialog_content = "Bem, como você está sempre tão ocupado, não tem realmente tempo para fazer outra coisa além de entregar cartas.",
  ui_story_31150601_63_option_content = "Claro que não!",
