  ui_story_31150601_69_dialog_content = "Isso costumava ser a única consideração quando se tratava de entregar cartas—",
  ui_story_31150601_70_dialog_content = "Mas novas possibilidades se abriram.",
  ui_story_31150601_71_dialog_content = "Acho que aqueles novatos estavam lá para te lembrar disso.",
  ui_story_31150601_72_dialog_content = "Sim... Eu li cuidadosamente as opiniões dos clientes que eles coletaram depois disso.",
  ui_story_31150601_73_dialog_content = "Eu nunca teria adivinhado que o público tinha tantas opiniões sobre o sindicato antes disso.",
  ui_story_31150601_74_dialog_content = "É apenas porque você está tão imerso em seu trabalho que negligencia a possibilidade de desenvolvimento futuro.",
  ui_story_31150601_75_dialog_content = "Faz sentido...",
  ui_story_31150601_76_dialog_content = "Eu deveria dar um passo atrás de vez em quando, como Wendy disse...",
  ui_story_31150601_77_dialog_content = "De repente, me lembro da minha infância em Northland.",
  ui_story_31150601_78_dialog_content = "O píer com treliças no verão... é tão diferente da paisagem de lá.",
  ui_story_31150601_79_dialog_content = "Tenho corrido para lá e para cá, ocupando-me com o trabalho todo esse tempo, nem mesmo tirei um tempo para olhar bem para o céu azul acima de mim.",
  ui_story_31150601_80_dialog_content = "Fico feliz que você finalmente percebeu isso!",
  ui_story_31150601_81_dialog_content = "Já que estamos todos de férias, não vamos falar mais sobre trabalho. Vamos apenas aproveitar a diversão de estar à beira-mar!",
  ui_story_31150601_82_dialog_content = "Que tal irmos brincar na água?",
  ui_story_31150601_83_dialog_content = "Claro...",
  ui_story_31150601_84_dialog_content = "Hã... a água está um pouco fria.",
  ui_story_31150601_85_dialog_content = "Bem, eu acho que quanto mais quente o clima, mais fresco o mar parece.",
  ui_story_31150601_86_dialog_content = "A sensação de flutuar na água é tão relaxante.",
  ui_story_31150601_87_dialog_content = "Hã? O que é isso?",
  ui_story_31150601_88_dialog_content = "É uma garrafa?",
  ui_story_31150601_89_dialog_content = "Parece haver uma mensagem enrolada dentro dele.",
  ui_story_31150601_90_dialog_content = "Abra!",
  ui_story_31150601_91_dialog_content = "Devo?",
  ui_story_31150601_92_dialog_content = "Claro que sim! É uma carta sem mensageiro! Isso significa que qualquer um pode lê-la!",
  ui_story_31150601_93_dialog_content = "Vamos dar uma olhada...",
  ui_story_31150601_94_dialog_content = "\"Mar lindo lindo, por favor, realize meu desejo de aniversário.\"",
  ui_story_31150601_95_dialog_content = "\"Espero que mamãe e papai fiquem juntos para sempre e comemorem meu aniversário todos os anos.\"",
  ui_story_31150601_96_dialog_content = "\"Se as coisas pudessem ser como são agora... Eu seria tão feliz, agora e sempre.\"",
  ui_story_31150601_97_dialog_content = "\"Querido querido mar, se for possível, eu também quero me tornar um superstar quando crescer...\"",
  ui_story_31150601_98_dialog_content = "Pfffff—",
  ui_story_31150601_99_dialog_content = "Essa garotinha é muito fofa.",
  ui_story_31150601_100_dialog_content = "Ela escreveu tantos desejos. Eu me pergunto se algum deles se tornará realidade.",
  ui_story_31150601_101_dialog_content = "Heheh, estarei orando por ela.",
  ui_story_31150601_102_dialog_content = "De fato. As ondas serviram como mensageiro desta carta...",
  ui_story_31150601_103_dialog_content = "Esta garrafa não tem destinatário, pois representa apenas os desejos de alguém.",
  ui_story_31150601_104_dialog_content = "Entendo agora...",
  ui_story_31150601_105_dialog_content = "A União Mensageira pode fornecer mais serviços de acordo com as necessidades das pessoas—",
  ui_story_31150601_106_dialog_content = "Como mensagens em uma garrafa.",
  ui_story_31150601_107_dialog_content = "Algumas formas de envio existem apenas por diversão.",
  ui_story_31150601_108_dialog_content = "A União Mensageira pode fornecer um serviço de mensagem em uma garrafa sem um destinatário fixo para pessoas longe do mar. Pode acabar sendo um sucesso.",
  ui_story_31150601_109_dialog_content = "Hmm, e se expandirmos nosso pensamento ainda mais...",
  ui_story_31150601_110_dialog_content = "Também podemos instituir serviços de entrega de mensagens programadas, como um serviço em que você pode enviar mensagens para si mesmo no futuro.",
  ui_story_31150601_111_dialog_content = "Oh! Essa é o tipo de ideia que só poderia vir da mente de um mensageiro experiente! É realmente interessante!",
  ui_story_31150601_112_dialog_content = "Entregar cartas em momentos diferentes proporcionará uma experiência diferente.",
  ui_story_31150601_113_dialog_content = "Acho que também poderíamos organizar uma atividade de correspondência anônima entre amigos por correspondência—",
  ui_story_31150601_114_dialog_content = "Even pessoas sem cartas para enviar ainda podem encontrar um motivo para se comunicar com outras através deste tipo de atividade.",
  ui_story_31150601_115_dialog_content = "Confiar apenas no destino para unir completos desconhecidos. Que ideia maravilhosa!",
  ui_story_31150601_116_dialog_content = "Você me deu tantas ideias empolgantes, PlayerName.",
  ui_story_31150601_117_dialog_content = "Gostaria de agradecer... por abrir minha mente.",
  ui_story_31150601_118_dialog_content = "Vou contar a todos sobre os novos arranjos de trabalho assim que retornar para casa.",
  ui_story_31150601_119_dialog_content = "E agora, posso aproveitar o resto das minhas férias sem preocupações no mundo!",
  ui_story_31150601_120_dialog_content = "Bem, talvez não...",
  ui_story_31150601_121_dialog_content = "Hum?",
  ui_story_31150601_122_dialog_content = "<color=#e8d9bb>Uma mistura de penas coloridas flutua até a superfície do mar, enquanto Olive, a cabeça do espírito do cuco, fica presa na garrafa que deriva nas ondas.</color>",
  ui_story_31150601_123_dialog_content = "<size=45>Azeitona!!!</size>",
  ui_story_31150601_124_dialog_content = "Squawk!",
  ui_story_31150601_125_dialog_content = "Você, pequeno pássaro curioso... Consegue entender o que está escrito naquele pedaço de papel?",
  ui_story_31150601_126_dialog_content = "Squawk—!!! Squawk!!!",
  ui_story_31150601_127_dialog_content = "Espere, deixe-me ajudá-lo..."
}
return config
